def page(filename, title, content, description):
    links = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url == filename else '')+f'>{label}</a>' for url, label in NAV)
    html = f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(description, quote=True)}"><meta name="theme-color" content="#111410">
<meta property="og:title" content="{escape(title)} | Ashraful Islam Tutul"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:type" content="website">
<title>{escape(title)} | Ashraful Islam Tutul</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="portfolio.css"><script src="portfolio.js" defer></script></head>
<body><a class="skip-link button" href="#main">Skip to content</a><header class="topbar"><nav class="shell nav" aria-label="Main navigation"><a class="brand" href="index.html" aria-label="Ashraf home">ashraf<span>.</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu +</button><div class="nav-links" id="navigation">{links}<a class="nav-contact" href="contact.html"{' aria-current="page"' if filename == 'contact.html' else ''}>Contact</a></div></nav></header>
<main id="main" class="shell">{content}{'' if filename == 'contact.html' else contact_cta}</main>
<footer class="footer"><div class="shell footer-inner"><span>© 2026 Ashraful Islam Tutul · Built with curiosity.</span><div class="socials"><a href="https://github.com/shraf2004" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="https://www.linkedin.com/in/shraf/" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="mailto:ashraftutulown@gmail.com">Email ↗</a></div></div></footer></body></html>'''
    (ROOT / filename).write_text(html, encoding='utf-8')

