def card(p):
    links=''.join(f'<a href="{u}" target="_blank" rel="noopener noreferrer">{label} ↗</a>' for label,u in p['links'])
    return f'''<article class="project-card reveal" data-category="{p['category']}"><div class="project-visual {p['visual']}" aria-hidden="true"><span class="visual-word">{p['word']}</span></div><div class="project-content"><div class="card-meta"><span>{p['event']}</span><span class="award">{p['award']}</span></div><h3>{p['name']}</h3><p>{p['desc']}</p>{tags(p['tech'])}{'<div class="card-links">'+links+'</div>' if links else ''}</div></article>'''

